/**
 * TASK: Track which child button the mouse is hovering over.
 *
 * This panel implements MouseListener and the constructor already registers
 * it on all three buttons ("one", "two", "three"). Complete mouseEntered and
 * mouseExited:
 *
 *   mouseEntered -- remember the name of the component the mouse entered,
 *                   add 1 to the enter counter, and set the label named
 *                   "status" to "over " + that name
 *   mouseExited  -- IGNORE the event unless it comes from the component that
 *                   is currently hovered; when it does match, forget the
 *                   hovered component and set the status label to "idle"
 *
 * That guard matters: moving from one button straight onto another can
 * deliver the exit for the OLD button after the enter for the new one, and a
 * naive mouseExited would then wipe out a hover that is still going on.
 *
 * hoveredName() returns the hovered component's name, or "none" when the
 * mouse is over no button at all.
 *
 * Example: enter "one", enter "two", exit "one" -> hoveredName() is still
 * "two" and the status label still reads "over two".
 *
 * Get the component from the event with e.getComponent().
 *
 * No window is ever opened -- the tests build MouseEvents by hand and hand
 * them to the buttons with dispatchEvent.
 */
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class HoverStatusPanel extends JPanel implements MouseListener {

    private final JLabel status = new JLabel("idle");
    private String hovered = null;
    private int enters = 0;

    public HoverStatusPanel() {
        status.setName("status");
        add(status);
        for (String name : new String[] { "one", "two", "three" }) {
            JButton button = new JButton(name);
            button.setName(name);
            button.addMouseListener(this);
            add(button);
        }
    }

    @Override
    public void mouseEntered(MouseEvent e) {
        // TODO: record the hover, count it, and update the status label
    }

    @Override
    public void mouseExited(MouseEvent e) {
        // TODO: only clear the hover when this event is for the hovered
        // TODO: component, then set the status label back to "idle"
    }

    public String hoveredName() {
        // TODO: the hovered component's name, or "none"
        return "";
    }

    public int enterCount() {
        // TODO: how many mouseEntered events have arrived
        return 0;
    }

    @Override
