public class HoverStatusPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void send(java.awt.Container panel, String name, int id) {
        java.awt.Component target = find(panel, name);
        if (target != null) {
            target.dispatchEvent(new java.awt.event.MouseEvent(target, id,
                    System.currentTimeMillis(), 0, 5, 5, 0, false));
        }
    }

    static void enter(java.awt.Container panel, String name) {
        send(panel, name, java.awt.event.MouseEvent.MOUSE_ENTERED);
    }

    static void exit(java.awt.Container panel, String name) {
        send(panel, name, java.awt.event.MouseEvent.MOUSE_EXITED);
    }

    public static void main(String[] args) {
        try {
            HoverStatusPanel panel = new HoverStatusPanel();
            java.awt.Component status = find(panel, "status");

            check("nothing hovered at the start", "none", panel.hoveredName());
            check("status starts idle", "idle", textOf(status));

            enter(panel, "one");
            check("hovered after entering one", "one", panel.hoveredName());
            check("status after entering one", "over one", textOf(status));

            exit(panel, "two");
            check("an exit from another button is ignored", "one", panel.hoveredName());
            check("status unchanged by the stale exit", "over one", textOf(status));

            exit(panel, "one");
            check("hovered after the matching exit", "none", panel.hoveredName());
            check("status after the matching exit", "idle", textOf(status));

            enter(panel, "two");
            enter(panel, "three");
            exit(panel, "two");
            check("the newest hover survives a late exit", "three", panel.hoveredName());
            check("status follows the newest hover", "over three", textOf(status));
            check("every enter was counted", 3, panel.enterCount());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

