import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class HoverStatusPanel extends JPanel implements MouseListener {

    private final JLabel status = new JLabel("idle");
    private String hovered = null;
    private int enters = 0;

    public HoverStatusPanel() {
        status.setName("status");
        add(status);
        for (String name : new String[] { "one", "two", "three" }) {
            JButton button = new JButton(name);
            button.setName(name);
            button.addMouseListener(this);
            add(button);
        }
    }

    @Override
    public void mouseEntered(MouseEvent e) {
        hovered = e.getComponent().getName();
        enters++;
        status.setText("over " + hovered);
    }

    @Override
    public void mouseExited(MouseEvent e) {
        String leaving = e.getComponent().getName();
        if (leaving != null && leaving.equals(hovered)) {
            hovered = null;
            status.setText("idle");
        }
    }

    public String hoveredName() {
        return hovered == null ? "none" : hovered;
    }

    public int enterCount() {
        return enters;
    }

    @Override
    public void mouseClicked(MouseEvent e) {
        // not used
    }

    @Override
    public void mousePressed(MouseEvent e) {
        // not used
    }

    @Override
    public void mouseReleased(MouseEvent e) {
        // not used
    }
}
